import { createContext, useContext } from "react";

interface AccordionSectionContextType {
  isExpanded: boolean;
  sectionId: string;
  buttonId: string;
  handleToggle: () => void;
  sectionIndex: number;
}

export const AccordionSectionContext = createContext<AccordionSectionContextType | undefined>(
  undefined,
);

export const useAccordionSection = () => {
  const context = useContext(AccordionSectionContext);
  if (context === undefined) {
    throw new Error("useAccordionSection must be used within an AccordionSectionContext.Provider");
  }
  return context;
};
